/**
 * Procedural paper finishes generated by code and reproducible by seed:
 * crumple, fold, stain, burn, tear, damp, fade, blood, grain.
 * Deterministic PRNG: same seed, same pixels; never Math.random().
 */

export const EFFECTS = [
  // [type, nome, mesclagem inicial, parâmetros com padrão]
  ['crumple', 'Amassado', 'soft-light', { creases: 18 }],
  ['fold', 'Dobras', 'multiply', { horizontal: 2, vertical: 1 }],
  ['stain', 'Manchas de café', 'multiply', { count: 5, color: '#7a4a1e' }],
  ['burn', 'Bordas queimadas', 'normal', { depth: 0.08 }],
  ['tear', 'Borda rasgada', 'normal', { side: 'bottom', depth: 0.04 }],
  ['damp', 'Umidade', 'multiply', { color: '#8a7a5a' }],
  ['fade', 'Desbotado', 'screen', { color: '#efe6cf' }],
  ['blood', 'Sangue', 'multiply', { drops: 12, smear: true, color: '#6e0b0b' }],
  ['grain', 'Grão', 'overlay', { size: 1.5 }],
];

/**
 * Deterministic pseudo-random number generator (Mulberry32).
 */
export function createRng(seed) {
  let s = (Math.floor(seed) || 1) >>> 0;
  return function rand() {
    s = Math.imul(s ^ (s >>> 15), 2246822507) ^ Math.imul(s ^ (s >>> 13), 3266489909);
    s ^= s >>> 16;
    return (s >>> 0) / 4294967296;
  };
}

export function hexToRgb(hex) {
  const clean = String(hex || '').replace('#', '');
  if (clean.length === 3) {
    return [
      parseInt(clean[0] + clean[0], 16),
      parseInt(clean[1] + clean[1], 16),
      parseInt(clean[2] + clean[2], 16),
    ];
  }
  if (clean.length === 6) {
    return [
      parseInt(clean.slice(0, 2), 16),
      parseInt(clean.slice(2, 4), 16),
      parseInt(clean.slice(4, 6), 16),
    ];
  }
  return [0, 0, 0];
}

/**
 * Draws an effect into a canvas of the given size (px of the render).
 * (0, 0) is top-left of the canvas.
 */
export function drawEffect(ctx, width, height, { type, seed = 1, amount = 0.5, params = {} } = {}, scale = 1) {
  const W = Math.max(1, Math.round(width));
  const H = Math.max(1, Math.round(height));
  const amt = Math.max(0, Math.min(1, Number(amount ?? 0.5)));
  const rand = createRng(seed);

  switch (type) {
    case 'crumple':
      drawCrumple(ctx, W, H, amt, params, rand, scale);
      break;
    case 'fold':
      drawFold(ctx, W, H, amt, params, rand, scale);
      break;
    case 'stain':
      drawStain(ctx, W, H, amt, params, rand, scale);
      break;
    case 'burn':
      drawBurn(ctx, W, H, amt, params, rand, scale);
      break;
    case 'tear':
      drawTear(ctx, W, H, amt, params, rand, scale);
      break;
    case 'damp':
      drawDamp(ctx, W, H, amt, params, rand, scale);
      break;
    case 'fade':
      drawFade(ctx, W, H, amt, params, rand, scale);
      break;
    case 'blood':
      drawBlood(ctx, W, H, amt, params, rand, scale);
      break;
    case 'grain':
      drawGrain(ctx, W, H, amt, params, rand, scale);
      break;
    default:
      // Unknown effect: no-op
      break;
  }
}

/**
 * For the effects that cut the paper (burn, tear): the shape that remains.
 * white (#ffffff) = keep, transparent (alpha 0) = gone.
 */
export function drawCutMask(ctx, width, height, { type, seed = 1, amount = 0.5, params = {} } = {}, scale = 1) {
  const W = Math.max(1, Math.round(width));
  const H = Math.max(1, Math.round(height));
  const amt = Math.max(0, Math.min(1, Number(amount ?? 0.5)));

  // Base: everything kept
  ctx.save();
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, W, H);

  if (amt <= 0) {
    ctx.restore();
    return;
  }

  const rand = createRng(seed);

  if (type === 'burn') {
    const depth = Math.max(0.005, Math.min(0.4, Number(params.depth ?? 0.08)));
    const maxInset = Math.min(W, H) * depth * amt;
    const step = Math.max(4, 12 * scale);

    // Build the remaining inner polygon
    const pts = [];

    // Top edge (left to right)
    for (let x = 0; x <= W; x += step) {
      const jag = maxInset * (0.2 + 0.8 * rand());
      pts.push([x, jag]);
    }
    // Right edge (top to bottom)
    for (let y = 0; y <= H; y += step) {
      const jag = maxInset * (0.2 + 0.8 * rand());
      pts.push([W - jag, y]);
    }
    // Bottom edge (right to left)
    for (let x = W; x >= 0; x -= step) {
      const jag = maxInset * (0.2 + 0.8 * rand());
      pts.push([x, H - jag]);
    }
    // Left edge (bottom to top)
    for (let y = H; y >= 0; y -= step) {
      const jag = maxInset * (0.2 + 0.8 * rand());
      pts.push([jag, y]);
    }

    // Keep only inside the polygon
    ctx.globalCompositeOperation = 'destination-in';
    ctx.beginPath();
    pts.forEach(([px, py], i) => (i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py)));
    ctx.closePath();
    ctx.fill();
  } else if (type === 'tear') {
    const side = params.side || 'bottom';
    const depth = Math.max(0.005, Math.min(0.4, Number(params.depth ?? 0.04)));
    const refDim = side === 'left' || side === 'right' ? W : H;
    const tearDepth = refDim * depth * amt;
    const step = Math.max(3, 8 * scale);

    ctx.globalCompositeOperation = 'destination-out';
    ctx.beginPath();

    if (side === 'bottom') {
      ctx.moveTo(0, H);
      for (let x = 0; x <= W; x += step) {
        const jag = tearDepth * (0.15 + 0.85 * rand());
        ctx.lineTo(x, H - jag);
      }
      ctx.lineTo(W, H);
      ctx.closePath();
      ctx.fill();
    } else if (side === 'top') {
      ctx.moveTo(0, 0);
      for (let x = 0; x <= W; x += step) {
        const jag = tearDepth * (0.15 + 0.85 * rand());
        ctx.lineTo(x, jag);
      }
      ctx.lineTo(W, 0);
      ctx.closePath();
      ctx.fill();
    } else if (side === 'left') {
      ctx.moveTo(0, 0);
      for (let y = 0; y <= H; y += step) {
        const jag = tearDepth * (0.15 + 0.85 * rand());
        ctx.lineTo(jag, y);
      }
      ctx.lineTo(0, H);
      ctx.closePath();
      ctx.fill();
    } else if (side === 'right') {
      ctx.moveTo(W, 0);
      for (let y = 0; y <= H; y += step) {
        const jag = tearDepth * (0.15 + 0.85 * rand());
        ctx.lineTo(W - jag, y);
      }
      ctx.lineTo(W, H);
      ctx.closePath();
      ctx.fill();
    }
  }

  ctx.restore();
}

// --- Individual Effect Renderers ---

function drawCrumple(ctx, W, H, amt, params, rand, scale) {
  // Base 50% neutral gray for soft-light blend
  ctx.fillStyle = '#808080';
  ctx.fillRect(0, 0, W, H);

  if (amt <= 0) return;

  const count = Math.max(1, Math.round(params.creases ?? 18));
  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  for (let c = 0; c < count; c++) {
    const numSegs = 4 + Math.floor(rand() * 4);
    let x = rand() * W;
    let y = rand() * H;
    let angle = rand() * Math.PI * 2;

    const points = [[x, y]];
    for (let s = 0; s < numSegs; s++) {
      const segLen = (30 + rand() * 90) * scale;
      angle += (rand() - 0.5) * 1.2;
      x += Math.cos(angle) * segLen;
      y += Math.sin(angle) * segLen;
      points.push([x, y]);
    }

    // Shadow crease (black)
    ctx.strokeStyle = `rgba(0, 0, 0, ${0.42 * amt})`;
    ctx.lineWidth = Math.max(1, 2.2 * scale);
    ctx.beginPath();
    points.forEach(([px, py], i) => (i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py)));
    ctx.stroke();

    // Highlight crease (white, slightly offset)
    const offX = Math.cos(angle + Math.PI / 2) * (1.6 * scale);
    const offY = Math.sin(angle + Math.PI / 2) * (1.6 * scale);
    ctx.strokeStyle = `rgba(255, 255, 255, ${0.48 * amt})`;
    ctx.lineWidth = Math.max(1, 1.6 * scale);
    ctx.beginPath();
    points.forEach(([px, py], i) => (i === 0 ? ctx.moveTo(px + offX, py + offY) : ctx.lineTo(px + offX, py + offY)));
    ctx.stroke();

    // Soft triangular gradient shading between corners
    if (points.length >= 3 && rand() > 0.4) {
      const p1 = points[0];
      const p2 = points[Math.floor(points.length / 2)];
      const p3 = points[points.length - 1];
      ctx.fillStyle = rand() > 0.5 ? `rgba(0, 0, 0, ${0.08 * amt})` : `rgba(255, 255, 255, ${0.08 * amt})`;
      ctx.beginPath();
      ctx.moveTo(p1[0], p1[1]);
      ctx.lineTo(p2[0], p2[1]);
      ctx.lineTo(p3[0], p3[1]);
      ctx.closePath();
      ctx.fill();
    }
  }

  ctx.restore();
}

function drawFold(ctx, W, H, amt, params, rand, scale) {
  // Base white for multiply blend (white = neutral)
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, W, H);

  if (amt <= 0) return;

  const horiz = Math.max(0, Math.round(params.horizontal ?? 2));
  const vert = Math.max(0, Math.round(params.vertical ?? 1));
  const band = Math.max(6, 14 * scale);

  // Horizontal folds
  for (let k = 1; k <= horiz; k++) {
    const y = Math.round(H * (k / (horiz + 1)));
    const g = ctx.createLinearGradient(0, y - band, 0, y + band);
    g.addColorStop(0, '#ffffff');
    g.addColorStop(0.42, '#ffffff');
    // Dark crease line at center
    const darkAlpha = Math.min(1, 0.45 * amt);
    g.addColorStop(0.5, `rgba(140, 130, 120, ${darkAlpha})`);
    g.addColorStop(0.52, '#ffffff');
    g.addColorStop(1, '#ffffff');

    ctx.fillStyle = g;
    ctx.fillRect(0, y - band, W, band * 2);
  }

  // Vertical folds
  for (let k = 1; k <= vert; k++) {
    const x = Math.round(W * (k / (vert + 1)));
    const g = ctx.createLinearGradient(x - band, 0, x + band, 0);
    g.addColorStop(0, '#ffffff');
    g.addColorStop(0.42, '#ffffff');
    const darkAlpha = Math.min(1, 0.45 * amt);
    g.addColorStop(0.5, `rgba(140, 130, 120, ${darkAlpha})`);
    g.addColorStop(0.52, '#ffffff');
    g.addColorStop(1, '#ffffff');

    ctx.fillStyle = g;
    ctx.fillRect(x - band, 0, band * 2, H);
  }
}

function drawStain(ctx, W, H, amt, params, rand, scale) {
  // Base white for multiply
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, W, H);

  if (amt <= 0) return;

  const count = Math.max(1, Math.round(params.count ?? 5));
  const [r, g, b] = hexToRgb(params.color || '#7a4a1e');

  for (let i = 0; i < count; i++) {
    const cx = rand() * W;
    const cy = rand() * H;
    const radius = (0.05 + rand() * 0.16) * Math.min(W, H);

    // 1. Coffee ring: radial gradient with darker outer edge
    const grad = ctx.createRadialGradient(cx, cy, radius * 0.2, cx, cy, radius);
    grad.addColorStop(0, `rgba(${r}, ${g}, ${b}, ${0.04 * amt})`);
    grad.addColorStop(0.72, `rgba(${r}, ${g}, ${b}, ${0.12 * amt})`);
    grad.addColorStop(0.88, `rgba(${r}, ${g}, ${b}, ${0.55 * amt})`);
    grad.addColorStop(0.96, `rgba(${r}, ${g}, ${b}, ${0.65 * amt})`);
    grad.addColorStop(1, '#ffffff');

    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.fill();

    // 2. Irregular coffee blotch (deformed polygon)
    const blotchRad = radius * 0.5;
    const numPts = 16;
    ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${0.18 * amt})`;
    ctx.beginPath();
    for (let p = 0; p < numPts; p++) {
      const theta = (p / numPts) * Math.PI * 2;
      const radDist = blotchRad * (0.6 + 0.4 * rand());
      const px = cx + Math.cos(theta) * radDist;
      const py = cy + Math.sin(theta) * radDist;
      if (p === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fill();

    // 3. Tiny splatter drops
    const numDrops = 3 + Math.floor(rand() * 5);
    for (let d = 0; d < numDrops; d++) {
      const dropAngle = rand() * Math.PI * 2;
      const dropDist = radius * (1.1 + rand() * 0.6);
      const dx = cx + Math.cos(dropAngle) * dropDist;
      const dy = cy + Math.sin(dropAngle) * dropDist;
      const dropR = (1 + rand() * 3) * scale;
      ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${0.45 * amt})`;
      ctx.beginPath();
      ctx.arc(dx, dy, dropR, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

function drawBurn(ctx, W, H, amt, params, rand, scale) {
  // Clear canvas (burn is drawn in normal blend on top of remaining paper)
  ctx.clearRect(0, 0, W, H);

  if (amt <= 0) return;

  const depth = Math.max(0.005, Math.min(0.4, Number(params.depth ?? 0.08)));
  const maxInset = Math.min(W, H) * depth * amt;
  const burnBand = maxInset * 1.5;

  // Draw scorched gradient along all 4 borders
  ctx.save();

  // Top scorched gradient
  const topGrad = ctx.createLinearGradient(0, 0, 0, burnBand);
  topGrad.addColorStop(0, `rgba(0, 0, 0, ${0.95 * amt})`);
  topGrad.addColorStop(0.35, `rgba(60, 20, 5, ${0.85 * amt})`);
  topGrad.addColorStop(0.75, `rgba(110, 50, 15, ${0.45 * amt})`);
  topGrad.addColorStop(1, 'rgba(110, 50, 15, 0)');
  ctx.fillStyle = topGrad;
  ctx.fillRect(0, 0, W, burnBand);

  // Bottom scorched gradient
  const btmGrad = ctx.createLinearGradient(0, H, 0, H - burnBand);
  btmGrad.addColorStop(0, `rgba(0, 0, 0, ${0.95 * amt})`);
  btmGrad.addColorStop(0.35, `rgba(60, 20, 5, ${0.85 * amt})`);
  btmGrad.addColorStop(0.75, `rgba(110, 50, 15, ${0.45 * amt})`);
  btmGrad.addColorStop(1, 'rgba(110, 50, 15, 0)');
  ctx.fillStyle = btmGrad;
  ctx.fillRect(0, H - burnBand, W, burnBand);

  // Left scorched gradient
  const lftGrad = ctx.createLinearGradient(0, 0, burnBand, 0);
  lftGrad.addColorStop(0, `rgba(0, 0, 0, ${0.95 * amt})`);
  lftGrad.addColorStop(0.35, `rgba(60, 20, 5, ${0.85 * amt})`);
  lftGrad.addColorStop(0.75, `rgba(110, 50, 15, ${0.45 * amt})`);
  lftGrad.addColorStop(1, 'rgba(110, 50, 15, 0)');
  ctx.fillStyle = lftGrad;
  ctx.fillRect(0, 0, burnBand, H);

  // Right scorched gradient
  const rgtGrad = ctx.createLinearGradient(W, 0, W - burnBand, 0);
  rgtGrad.addColorStop(0, `rgba(0, 0, 0, ${0.95 * amt})`);
  rgtGrad.addColorStop(0.35, `rgba(60, 20, 5, ${0.85 * amt})`);
  rgtGrad.addColorStop(0.75, `rgba(110, 50, 15, ${0.45 * amt})`);
  rgtGrad.addColorStop(1, 'rgba(110, 50, 15, 0)');
  ctx.fillStyle = rgtGrad;
  ctx.fillRect(W - burnBand, 0, burnBand, H);

  ctx.restore();
}

function drawTear(ctx, W, H, amt, params, rand, scale) {
  ctx.clearRect(0, 0, W, H);

  if (amt <= 0) return;

  const side = params.side || 'bottom';
  const depth = Math.max(0.005, Math.min(0.4, Number(params.depth ?? 0.04)));
  const refDim = side === 'left' || side === 'right' ? W : H;
  const tearDepth = refDim * depth * amt;
  const step = Math.max(3, 8 * scale);

  ctx.save();
  ctx.lineWidth = Math.max(1, 1.8 * scale);
  ctx.strokeStyle = `rgba(255, 255, 255, ${0.92 * amt})`; // paper fiber highlight

  if (side === 'bottom') {
    ctx.beginPath();
    for (let x = 0; x <= W; x += step) {
      const jag = tearDepth * (0.15 + 0.85 * rand());
      if (x === 0) ctx.moveTo(x, H - jag);
      else ctx.lineTo(x, H - jag);
    }
    ctx.stroke();
  } else if (side === 'top') {
    ctx.beginPath();
    for (let x = 0; x <= W; x += step) {
      const jag = tearDepth * (0.15 + 0.85 * rand());
      if (x === 0) ctx.moveTo(x, jag);
      else ctx.lineTo(x, jag);
    }
    ctx.stroke();
  } else if (side === 'left') {
    ctx.beginPath();
    for (let y = 0; y <= H; y += step) {
      const jag = tearDepth * (0.15 + 0.85 * rand());
      if (y === 0) ctx.moveTo(jag, y);
      else ctx.lineTo(jag, y);
    }
    ctx.stroke();
  } else if (side === 'right') {
    ctx.beginPath();
    for (let y = 0; y <= H; y += step) {
      const jag = tearDepth * (0.15 + 0.85 * rand());
      if (y === 0) ctx.moveTo(W - jag, y);
      else ctx.lineTo(W - jag, y);
    }
    ctx.stroke();
  }

  ctx.restore();
}

function drawDamp(ctx, W, H, amt, params, rand, scale) {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, W, H);

  if (amt <= 0) return;

  const [r, g, b] = hexToRgb(params.color || '#8a7a5a');
  const count = 3 + Math.floor(rand() * 3);

  ctx.save();
  for (let i = 0; i < count; i++) {
    const cx = rand() * W;
    const cy = rand() * H;
    const rad = (0.12 + rand() * 0.22) * Math.min(W, H);
    const numPts = 24;
    const pts = [];

    for (let p = 0; p < numPts; p++) {
      const angle = (p / numPts) * Math.PI * 2;
      const d = rad * (0.65 + 0.35 * rand());
      pts.push([cx + Math.cos(angle) * d, cy + Math.sin(angle) * d]);
    }

    // Interior wash
    ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${0.1 * amt})`;
    ctx.beginPath();
    pts.forEach(([px, py], idx) => (idx === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py)));
    ctx.closePath();
    ctx.fill();

    // Darker dry-edge perimeter ring
    ctx.strokeStyle = `rgba(${r}, ${g}, ${b}, ${0.4 * amt})`;
    ctx.lineWidth = Math.max(1, 2.4 * scale);
    ctx.stroke();
  }
  ctx.restore();
}

function drawFade(ctx, W, H, amt, params, rand, scale) {
  // Screen blend base is black (#000000 = neutral)
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, W, H);

  if (amt <= 0) return;

  const [r, g, b] = hexToRgb(params.color || '#efe6cf');

  // Radial wash from center
  const cx = W / 2 + (rand() - 0.5) * (W * 0.2);
  const cy = H / 2 + (rand() - 0.5) * (H * 0.2);
  const maxR = Math.hypot(W, H) * 0.55;

  const grad = ctx.createRadialGradient(cx, cy, maxR * 0.1, cx, cy, maxR);
  grad.addColorStop(0, `rgba(${r}, ${g}, ${b}, ${0.5 * amt})`);
  grad.addColorStop(0.5, `rgba(${r}, ${g}, ${b}, ${0.28 * amt})`);
  grad.addColorStop(1, `rgba(${r}, ${g}, ${b}, ${0.08 * amt})`);

  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);
}

function drawBlood(ctx, W, H, amt, params, rand, scale) {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, W, H);

  if (amt <= 0) return;

  const drops = Math.max(1, Math.round(params.drops ?? 12));
  const [r, g, b] = hexToRgb(params.color || '#6e0b0b');
  const smear = params.smear !== false;

  ctx.save();

  // Smear / Drag trail
  if (smear) {
    const startX = rand() * W * 0.7;
    const startY = rand() * H * 0.7;
    const length = (80 + rand() * 160) * scale;
    const angle = rand() * Math.PI * 2;
    const endX = startX + Math.cos(angle) * length;
    const endY = startY + Math.sin(angle) * length;

    // Draw wide dragged stroke with streaks
    const numStreaks = 4;
    for (let s = 0; s < numStreaks; s++) {
      const offset = (s - numStreaks / 2) * (5 * scale);
      const perpX = Math.cos(angle + Math.PI / 2) * offset;
      const perpY = Math.sin(angle + Math.PI / 2) * offset;

      ctx.strokeStyle = `rgba(${r}, ${g}, ${b}, ${(0.3 + rand() * 0.4) * amt})`;
      ctx.lineWidth = (4 + rand() * 12) * scale;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(startX + perpX, startY + perpY);
      ctx.lineTo(endX + perpX + (rand() - 0.5) * 10 * scale, endY + perpY + (rand() - 0.5) * 10 * scale);
      ctx.stroke();
    }
  }

  // Droplets and splatters
  for (let i = 0; i < drops; i++) {
    const dx = rand() * W;
    const dy = rand() * H;
    const dropRad = (2 + rand() * 9) * scale;
    const splatterAngle = rand() * Math.PI * 2;

    // Core droplet (crimson)
    ctx.fillStyle = `rgba(${Math.max(0, r - 30)}, ${Math.max(0, g - 5)}, ${Math.max(0, b - 5)}, ${0.9 * amt})`;
    ctx.beginPath();
    ctx.arc(dx, dy, dropRad, 0, Math.PI * 2);
    ctx.fill();

    // Splatter tail
    const tailLen = dropRad * (1.5 + rand() * 2.5);
    const tipX = dx + Math.cos(splatterAngle) * tailLen;
    const tipY = dy + Math.sin(splatterAngle) * tailLen;
    ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${0.75 * amt})`;
    ctx.beginPath();
    ctx.moveTo(dx - Math.sin(splatterAngle) * dropRad * 0.8, dy + Math.cos(splatterAngle) * dropRad * 0.8);
    ctx.lineTo(tipX, tipY);
    ctx.lineTo(dx + Math.sin(splatterAngle) * dropRad * 0.8, dy - Math.cos(splatterAngle) * dropRad * 0.8);
    ctx.closePath();
    ctx.fill();

    // Satellite micro-droplets
    const microCount = 3 + Math.floor(rand() * 5);
    for (let m = 0; m < microCount; m++) {
      const spread = (rand() - 0.5) * 0.8;
      const dist = tailLen * (1.1 + rand() * 1.2);
      const mx = dx + Math.cos(splatterAngle + spread) * dist;
      const my = dy + Math.sin(splatterAngle + spread) * dist;
      ctx.beginPath();
      ctx.arc(mx, my, Math.max(1, (0.8 + rand() * 2) * scale), 0, Math.PI * 2);
      ctx.fill();
    }
  }

  ctx.restore();
}

function drawGrain(ctx, W, H, amt, params, rand, scale) {
  // Overlay base is 50% gray (#808080 = neutral)
  ctx.fillStyle = '#808080';
  ctx.fillRect(0, 0, W, H);

  if (amt <= 0) return;

  const bs = Math.max(1, Math.round((params.size ?? 1.5) * scale));

  // If using standard canvas with getImageData
  try {
    const imgData = ctx.getImageData(0, 0, W, H);
    const data = imgData.data;
    const stride = W * 4;

    for (let y = 0; y < H; y += bs) {
      for (let x = 0; x < W; x += bs) {
        const noise = (rand() - 0.5) * 255 * amt * 0.75;
        const val = Math.max(0, Math.min(255, Math.round(128 + noise)));

        // Fill bs x bs block
        for (let dy = 0; dy < bs && y + dy < H; dy++) {
          const rowStart = (y + dy) * stride;
          for (let dx = 0; dx < bs && x + dx < W; dx++) {
            const idx = rowStart + (x + dx) * 4;
            data[idx] = val;
            data[idx + 1] = val;
            data[idx + 2] = val;
            data[idx + 3] = 255;
          }
        }
      }
    }
    ctx.putImageData(imgData, 0, 0);
  } catch {
    // Fallback using fillRect
    for (let y = 0; y < H; y += bs) {
      for (let x = 0; x < W; x += bs) {
        const noise = (rand() - 0.5) * 255 * amt * 0.75;
        const val = Math.max(0, Math.min(255, Math.round(128 + noise)));
        ctx.fillStyle = `rgb(${val}, ${val}, ${val})`;
        ctx.fillRect(x, y, bs, bs);
      }
    }
  }
}

